/** Public entry point — the only module consumers/docs should import from. */

export {
  useDataGridLazyRows,
  type UseDataGridLazyRowsOptions,
  type UseDataGridLazyRowsResult,
  type LazyFetchContext,
} from "./use-data-grid-lazy-rows";
export { DataGridLazyGuard, type DataGridLazyGuardProps } from "./lazy-guard";
export { type Range } from "./range-math";
export {
  useDataGridInfiniteRows,
  type UseDataGridInfiniteRowsOptions,
  type UseDataGridInfiniteRowsResult,
  type InfiniteFetchContext,
  type InfiniteFetchResult,
} from "./use-data-grid-infinite-rows";
export { serverSpecKey, type ServerSpec } from "./server-spec";

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { applyChange, type DataChange } from "@/registry/default/components/data-grid/data-grid";
import { holeRowId, isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { EMPTY_SERVER_SPEC, serverSpecKey, type ServerSpec } from "./server-spec";
import { chunkRange, expandRange, mergeRanges, rangeSize, subtractRanges, sumRangeSizes, type Range } from "./range-math";

/** Default extra rows fetched per range beyond the visible window — ~1 viewport (spec: "default ~1 viewport of rows"). */
const DEFAULT_OVERSCAN = 30;
/** Default rounding unit for fetch ranges (spec: "round ranges up so tiny scrolls don't spam requests"). */
const DEFAULT_PAGE_SIZE = 50;

/** Options for {@link useDataGridLazyRows}. */
export type LazyFetchContext = {
  /** First row to fetch. */
  start: number;
  /** One past the last row to fetch. */
  end: number;
  signal: AbortSignal;
  /** The sort, filter, and search that were current when the request started. */
  spec: ServerSpec;
};

export type UseDataGridLazyRowsOptions<TData> = {
  /** Total row count across the whole dataset, loaded or not — sizes the sparse `data` array. */
  total: number;
  /**
   * Fetches rows `[start, end)` (inclusive-exclusive, matching `onRenderedRowsChange`'s convention).
   * Must resolve with EXACTLY `end - start` rows, positionally aligned to `[start, end)` (the row
   * at index `start + i` at result index `i`). A short response leaves the unwritten rows unloaded
   * (only actually written rows are marked loaded, so the gap refetches on next visibility); an
   * over-long one has its tail dropped (clamped to `[start, end)`). Either mismatch dev-warns —
   * unclamped, both would poison the range cache permanently.
   */
  fetchRows: (ctx: LazyFetchContext) => Promise<TData[]>;
  getRowId: (row: TData, index: number) => string;
  /** The sort, filter, and search of your request, handed back to `fetchRows`. A change of its content resets the hook like `reset()`. */
  spec?: ServerSpec;
  /** Extra rows fetched per range beyond the visible window; default 30. */
  overscan?: number;
  /** Rounds fetch ranges to this boundary so small scrolls reuse the same page; default 50. */
  pageSize?: number;
  /**
   * Caps rows per single `fetchRows` call: a gap wider than this is split into consecutive
   * chunks of at most `maxFetchRows` rows, each fetched independently (own dedup, abort, and
   * failure). Chunk boundaries follow the gap's start, not `pageSize` boundaries. Non-integer
   * values are rounded down; values below 1 are treated as 1. Default: no cap.
   */
  maxFetchRows?: number;
  /** Fired when a range fetch throws/rejects; the range reverts to unloaded and is retried next time it's visible, or on `retry()`. */
  onError?: (error: unknown) => void;
  /**
   * Fired once a range fetch resolves and the hook has marked that range loaded, with the range
   * that was actually written — a short response is clamped, so it can be smaller than the
   * requested range. The rows commit on the next render, so this hook's `data` is still stale
   * inside the callback; `getLoadedRanges()` already includes the range. Not fired for aborted
   * or rejected fetches, nor when the response wrote zero rows.
   */
  onLoaded?: (range: Range) => void;
};

/** Return value of {@link useDataGridLazyRows}. */
export type UseDataGridLazyRowsResult<TData> = {
  /**
   * Spread onto `<DataGrid {...lazy.gridProps} columns={columns} />`. `data` is typed
   * `readonly TData[]` to match `DataGridProps` but is genuinely sparse at runtime (holes =
   * unloaded rows) — same convention the core skeleton-row contract itself uses (`useDataGridRow`
   * returns `undefined` for a hole regardless of `TData`'s declared element type).
   */
  gridProps: {
    data: readonly TData[];
    getRowId: (row: TData, index: number) => string;
    onRenderedRowsChange: (range: Range) => void;
    /** `total`, so the provider needs no second count. */
    totalRowCount: number;
  };
  /**
   * Pass as `DataGrid`'s `onDataChange` to let edits on already-loaded rows flow back into the
   * sparse array normally (see the hook's doc comment for why edits are handled this way).
   */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Count of indices with no loaded row yet — mainly for the sort/filter dev-warn guard and diagnostics. */
  unloadedCount: number;
  /** True while any range fetch is in flight. Use it for a busy state, e.g. `aria-busy` or a dimmed grid while a server-side sort refetches. */
  isLoading: boolean;
  /**
   * Aborts every in-flight fetch, drops all loaded rows, and re-requests the last reported
   * window, so rows currently in view refetch instead of sitting as skeletons — the same reset
   * a `total` change performs, callable whenever the dataset behind the same `total` is
   * invalidated in place (a server-side refresh, a sort spec change). Stable across renders.
   */
  reset: () => void;
  /** Re-requests the last reported window: the ranges that failed fetch again. Stable across renders. */
  retry: () => void;
  /**
   * Unloads the loaded rows inside `range`; a partial overlap evicts the intersection only, the
   * rest stays loaded. The next `onRenderedRowsChange` covering the evicted rows re-fetches them.
   * In-flight fetches are not aborted — one started before the evict still lands and marks its
   * range loaded. Evicted rows are lost from the sparse array,
   * including edits merged through `onDataChange` (this hook does not own persistence). Clamped
   * to `[0, total]`; an empty or out-of-range target is a no-op. Stable across renders.
   */
  evict: (range: Range) => void;
  /**
   * Snapshot of the currently loaded ranges, merged and sorted ascending. Not reactive: the
   * ranges are kept in a ref so a fetch completion never triggers an extra render — the returned
   * array is a copy (mutating it does not affect this hook) and reading it never triggers a
   * render. Call it in effects or event handlers; treat a stale value during render as
   * acceptable. Stable across renders.
   */
  getLoadedRanges: () => readonly Range[];
};

/** A consumer callback throwing must not escape the fetch's promise chain as an unhandled rejection. */
function guardCallback(fn: (() => void) | undefined): void {
  try {
    fn?.();
  } catch (error) {
    console.error("[data-grid-lazy] a lazy-rows callback threw:", error);
  }
}

/**
 * Virtual data fetching for `DataGrid`: maintains a sparse
 * `data` array (length `total`, holes = unloaded rows) and fetches windows on demand as
 * `onRenderedRowsChange` reports the rendered range. Loaded rows are addressed by `getRowId`, so an
 * edit/sort of a loaded row behaves exactly like a normal controlled grid; unloaded rows use an
 * index-derived placeholder id purely so React has a key to render a skeleton row under.
 *
 * Editing: consumers pass this hook's `onDataChange` straight to `DataGrid`. It's a plain
 * `(next, change) => void` like core's own prop — this hook doesn't own a data setter itself
 * (no `data`/`onChange` tuple, unlike `useDataGridHistory`) because the sparse array's source of
 * truth is split between "what's loaded" (this hook) and "what the consumer's rows actually
 * contain" (the consumer's own store/cache) — the consumer's `onDataChange` is expected to persist
 * `change` (e.g. to its cache/backend) and this hook merges `next` back into the sparse positions
 * it already had loaded. Edits are only reachable on loaded rows in the first place: core's own
 * skeleton-cell handling blocks entering edit mode on an unloaded row.
 */
export function useDataGridLazyRows<TData>(options: UseDataGridLazyRowsOptions<TData>): UseDataGridLazyRowsResult<TData> {
  const {
    total,
    fetchRows,
    getRowId,
    overscan = DEFAULT_OVERSCAN,
    pageSize = DEFAULT_PAGE_SIZE,
    spec = EMPTY_SERVER_SPEC,
    maxFetchRows,
    onLoaded,
    onError,
  } = options;

  const [rows, setRows] = useState<(TData | undefined)[]>(() => Array<TData | undefined>(total));

  // Loaded + in-flight ranges, kept OUTSIDE React state: consulted synchronously inside the
  // onRenderedRowsChange handler (dedup must see the effect of the fetch it just started, same tick,
  // not next render) and mutated from fetch completion callbacks that must not themselves trigger
  // extra renders beyond the one `setRows` already causes.
  const loadedRangesRef = useRef<Range[]>([]);
  const inFlightRef = useRef<Map<string, { range: Range; controller: AbortController }>>(new Map());
  const [isLoading, setIsLoading] = useState(false);
  // per-instance once-flag: a persistently broken fetchRows must not re-warn on every fetch
  const lengthMismatchWarnedRef = useRef(false);
  const droppedEditWarnedRef = useRef(false);
  const lastWindowRef = useRef<Range | null>(null);
  const pendingWindowRef = useRef(false);

  // In-flight fetches are aborted so a slow resolution of the old dataset can't write stale rows.
  const totalRef = useRef(total);
  const reset = useCallback(() => {
    for (const { controller } of inFlightRef.current.values()) controller.abort();
    inFlightRef.current.clear();
    loadedRangesRef.current = [];
    setRows(new Array(totalRef.current));
    setIsLoading(false);
    // the core re-reports a window only when it moves — re-fire the last one or visible rows sit as skeletons.
    pendingWindowRef.current = lastWindowRef.current !== null;
  }, []);
  if (totalRef.current !== total) {
    totalRef.current = total;
    reset();
  }
  const specKey = serverSpecKey(spec);
  const specKeyRef = useRef(specKey);
  if (specKeyRef.current !== specKey) {
    specKeyRef.current = specKey;
    reset();
  }
  const specRef = useRef(spec);
  specRef.current = spec;

  const fetchRowsRef = useRef(fetchRows);
  fetchRowsRef.current = fetchRows;
  const onLoadedRef = useRef(onLoaded);
  onLoadedRef.current = onLoaded;
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;

  // Aborts every in-flight fetch on unmount — the spec's "abort-on-unmount via AbortSignal".
  useEffect(() => {
    const inFlight = inFlightRef.current;
    return () => {
      for (const { controller } of inFlight.values()) controller.abort();
      inFlight.clear();
    };
  }, []);

  const evict = useCallback(
    (range: Range) => {
      const start = Math.max(0, range.start);
      const end = Math.min(totalRef.current, range.end);
      if (end <= start) return;
      const target = { start, end };
      const kept: Range[] = [];
      for (const loaded of loadedRangesRef.current) {
        for (const piece of subtractRanges(loaded, [target])) kept.push(piece);
      }
      loadedRangesRef.current = mergeRanges(kept);
      setRows((prev) => {
        const next = prev.slice();
        for (let i = start; i < end; i++) next[i] = undefined;
        return next;
      });
    },
    [],
  );

  const getLoadedRanges = useCallback(() => loadedRangesRef.current.slice(), []);

  const runFetch = useCallback((range: Range) => {
    const key = `${range.start}:${range.end}`;
    if (inFlightRef.current.has(key)) return;
    const controller = new AbortController();
    inFlightRef.current.set(key, { range, controller });
    setIsLoading(true);

    const handleSettled = () => {
      // a reset() may have replaced this fetch under the same key — only the current owner clears it.
      const entry = inFlightRef.current.get(key);
      if (entry?.controller !== controller) return;
      inFlightRef.current.delete(key);
      if (inFlightRef.current.size === 0) setIsLoading(false);
    };
    const handleFulfilled = (fetched: TData[]) => {
      if (controller.signal.aborted) return;
      const expected = range.end - range.start;
      const written = Math.min(fetched.length, expected);
      if (fetched.length !== expected) {
        if (!lengthMismatchWarnedRef.current && isDev()) {
          lengthMismatchWarnedRef.current = true;
          console.warn(
            `[data-grid-lazy] fetchRows for rows [${range.start}, ${range.end}) resolved with ${fetched.length} rows, expected exactly ${expected} (it must return exactly end - start rows, positionally aligned to [start, end)); writes are clamped to the requested range and only the ${written} written rows are marked loaded`,
          );
        }
      }
      loadedRangesRef.current = mergeRanges([...loadedRangesRef.current, { start: range.start, end: range.start + written }]);
      setRows((prev) => {
        const next = prev.slice();
        for (let i = 0; i < written; i++) {
          next[range.start + i] = fetched[i];
        }
        return next;
      });
      if (written > 0) guardCallback(() => onLoadedRef.current?.({ start: range.start, end: range.start + written }));
    };
    const handleRejected = (error: unknown) => {
      if (controller.signal.aborted) return;
      // failed ranges revert to unloaded (never entered loadedRangesRef) so the next
      // onRenderedRowsChange covering them naturally retries — "refetch on next visibility".
      guardCallback(() => onErrorRef.current?.(error));
    };

    // try/catch guards a `fetchRows` that throws synchronously instead of returning a rejected
    // promise — inFlightRef is already set above, so without this a sync throw would leave the
    // range stuck "in flight" forever, permanently blocking any future refetch of it.
    try {
      fetchRowsRef.current({ start: range.start, end: range.end, signal: controller.signal, spec: specRef.current }).then(handleFulfilled, handleRejected).finally(handleSettled);
    } catch (error) {
      handleRejected(error);
      handleSettled();
    }
  }, []);

  const onRenderedRowsChange = useCallback(
    (range: Range) => {
      lastWindowRef.current = range;
      const expanded = expandRange(range, { overscan, batchSize: pageSize, total: totalRef.current });
      if (rangeSize(expanded) === 0) return;
      const covered = [...loadedRangesRef.current, ...Array.from(inFlightRef.current.values(), (v) => v.range)];
      const gaps = subtractRanges(expanded, covered);
      for (const gap of gaps) {
        for (const chunk of chunkRange(gap, maxFetchRows ?? Infinity)) runFetch(chunk);
      }
    },
    [overscan, pageSize, maxFetchRows, runFetch],
  );

  const retry = useCallback(() => {
    const last = lastWindowRef.current;
    if (last) onRenderedRowsChange(last);
  }, [onRenderedRowsChange]);

  // No deps: this must observe the flag on every commit, and the flag makes repeat runs a no-op.
  useEffect(() => {
    if (!pendingWindowRef.current) return;
    pendingWindowRef.current = false;
    const last = lastWindowRef.current;
    if (last) onRenderedRowsChange(last);
  });

  const gridGetRowId = useCallback(
    (row: TData, index: number) => (row === undefined ? holeRowId(index) : getRowId(row, index)),
    [getRowId],
  );

  const warnDroppedEdit = useCallback(
    (prev: readonly (TData | undefined)[], change: DataChange<TData>) => {
      const loadedIds = new Set<string>();
      prev.forEach((row, index) => {
        if (row !== undefined) loadedIds.add(getRowId(row, index));
      });
      const dropped = change.ops.find((op) => op.type !== "insert" && !loadedIds.has(op.rowId));
      if (!dropped) return;
      droppedEditWarnedRef.current = true;
      console.warn(
        `[data-grid-lazy] an edit to row "${dropped.rowId}" was dropped because the row was evicted before the change merged; this hook does not own persistence, so keep the edit in your own cache`,
      );
    },
    [getRowId],
  );

  const onDataChange = useCallback(
    (next: readonly TData[], change: DataChange<TData>) => {
      // `next` is DataGrid's own post-op snapshot, itself sparse at runtime (see gridProps.data's
      // doc) — and it can predate rows a just-resolved fetch already wrote into state, so replacing
      // the array with it drops those rows. With operations, re-apply them to the latest state instead
      // (ids-keyed, so the fetch's extra rows survive untouched); without operations, `next` is authoritative.
      setRows((prev) => {
        if (isDev() && !droppedEditWarnedRef.current) warnDroppedEdit(prev, change);
        return change.ops.length > 0
          ? (applyChange(prev as TData[], change, gridGetRowId) as (TData | undefined)[])
          : (next.slice() as (TData | undefined)[]);
      });
    },
    [gridGetRowId, warnDroppedEdit],
  );

  const gridProps = useMemo(
    () => ({
      data: rows as TData[],
      getRowId: gridGetRowId,
      onRenderedRowsChange,
      totalRowCount: total,
    }),
    [rows, gridGetRowId, onRenderedRowsChange, total],
  );

  // Derived from the loaded-ranges bookkeeping, not a rows.reduce scan: `rows` is a genuinely
  // sparse array (new Array(total) leaves true holes), and Array#reduce SKIPS holes entirely
  // rather than visiting them as `undefined`, so a scan would undercount every unloaded slot.
  const unloadedCount = totalRef.current - sumRangeSizes(loadedRangesRef.current);

  return { gridProps, onDataChange, unloadedCount, isLoading, reset, retry, evict, getLoadedRanges };
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { applyChange, type DataChange } from "@/registry/default/components/data-grid/data-grid";
import { holeRowId, isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { Range } from "./range-math";
import { EMPTY_SERVER_SPEC, serverSpecKey, type ServerSpec } from "./server-spec";

const DEFAULT_PAGE_SIZE = 50;
const DEFAULT_OVERSCAN = 30;

/** What `fetchRows` of {@link useDataGridInfiniteRows} receives. */
export type InfiniteFetchContext<TCursor> = {
  /** The `nextCursor` of the previous page; `undefined` for the first page. */
  cursor: TCursor | undefined;
  /** Position of the first requested row in the grid (the number of rows loaded so far). */
  start: number;
  /** Rows to ask for: `pageSize`, capped by `maxFetchRows`. The server may return fewer or more. */
  limit: number;
  signal: AbortSignal;
  /** The sort, filter, and search that were current when the request started. */
  spec: ServerSpec;
};

/** What `fetchRows` of {@link useDataGridInfiniteRows} resolves with. */
export type InfiniteFetchResult<TData, TCursor> = {
  rows: TData[];
  /** `null` ends the source. Any other value, including `0`, means more rows exist and is passed back as `cursor`. */
  nextCursor: TCursor | null;
};

/** Options for {@link useDataGridInfiniteRows}. */
export type UseDataGridInfiniteRowsOptions<TData, TCursor = unknown> = {
  /** Fetches the page after `cursor`. A rejection or a non-array `rows` calls `onError` and stops the chain until the window next reports. */
  fetchRows: (ctx: InfiniteFetchContext<TCursor>) => Promise<InfiniteFetchResult<TData, TCursor>>;
  getRowId: (row: TData, index: number) => string;
  /** The sort, filter, and search of your request, handed back to `fetchRows`. A change of its content resets the hook like `reset()`. */
  spec?: ServerSpec;
  /** Rows requested per fetch, and skeleton rows shown below the loaded rows while more exist. Default 50. */
  pageSize?: number;
  /** A fetch starts when the rendered window comes within this many rows of the loaded end. Default 30. */
  overscan?: number;
  /** Caps `limit` per fetch. Values below 1 are treated as 1. Default: no cap. */
  maxFetchRows?: number;
  /** Fired when a fetch fails. */
  onError?: (error: unknown) => void;
  /** Fired after a page is merged, with the range it filled. */
  onLoaded?: (range: Range) => void;
};

/** Return value of {@link useDataGridInfiniteRows}. */
export type UseDataGridInfiniteRowsResult<TData> = {
  /** Spread onto `<DataGrid />`. `data` is sparse: the last `pageSize` rows are holes while `hasNextPage`. */
  gridProps: {
    data: readonly TData[];
    getRowId: (row: TData, index: number) => string;
    onRenderedRowsChange: (range: Range) => void;
    /** The final count once the source ended, else `null`, so the provider needs no second count. */
    totalRowCount: number | null;
  };
  /** Pass as `onDataChange`. Edits, inserts, and deletes of loaded rows merge into the loaded rows. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** `undefined` while `hasNextPage`, then the final row count. */
  total: number | undefined;
  /** True until `fetchRows` returns a `null` or missing cursor (or an empty page). */
  hasNextPage: boolean;
  /** Skeleton rows below the loaded rows: `pageSize` while `hasNextPage`, else 0. */
  unloadedCount: number;
  isLoading: boolean;
  /** Aborts the fetch, drops every row and the cursor, and requests the first page again. Call it when sort, filter, or search changes. */
  reset: () => void;
  /** Repeats the fetch that failed. Stable across renders. */
  retry: () => void;
};

type Loaded<TData> = { rows: TData[]; hasNextPage: boolean };

function guardCallback(fn: () => void): void {
  try {
    fn();
  } catch (error) {
    console.error("[data-grid-lazy] an infinite-rows callback threw:", error);
  }
}

/**
 * Lazy rows for a source with no known total, such as a keyset or "has more" API. Pages load one
 * after the other, each with the cursor of the one before. The grid gets the loaded rows plus one
 * page of skeleton rows, so the scroll height grows in steps and ends exactly at the last row.
 * Sort, filter, and search live in the consumer's request; call `reset()` when they change.
 * The hook keeps every loaded row, so cap the source if it can grow without bound.
 */
export function useDataGridInfiniteRows<TData, TCursor = unknown>(
  options: UseDataGridInfiniteRowsOptions<TData, TCursor>,
): UseDataGridInfiniteRowsResult<TData> {
  const { getRowId, overscan = DEFAULT_OVERSCAN, maxFetchRows } = options;
  const pageSize = Number.isFinite(options.pageSize) && options.pageSize! >= 1 ? Math.floor(options.pageSize!) : DEFAULT_PAGE_SIZE;
  const [loaded, setLoaded] = useState<Loaded<TData>>({ rows: [], hasNextPage: true });
  const [isLoading, setIsLoading] = useState(false);

  // Written by every state transition below, so a handler reads the latest rows without waiting for a commit.
  const loadedRef = useRef(loaded);
  const cursorRef = useRef<TCursor | undefined>(undefined);
  const controllerRef = useRef<AbortController | null>(null);
  const lastWindowRef = useRef<Range | null>(null);
  const pendingWindowRef = useRef(false);
  const emptyPageWarnedRef = useRef(false);
  const cutWarnedRef = useRef(false);
  const cursorWarnedRef = useRef(false);
  const optionsRef = useRef(options);
  // A layout effect runs before the grid's passive effect that reports the first window, so a reset reads the new `fetchRows`.
  useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const limit = Math.max(1, Math.min(pageSize, maxFetchRows === undefined ? Infinity : Math.floor(maxFetchRows)));

  const fetchNext = useCallback(() => {
    const { rows, hasNextPage } = loadedRef.current;
    if (!hasNextPage || controllerRef.current) return;
    const controller = new AbortController();
    controllerRef.current = controller;
    setIsLoading(true);
    const start = rows.length;
    const spec = optionsRef.current.spec ?? EMPTY_SERVER_SPEC;

    const settle = () => {
      if (controllerRef.current !== controller) return;
      controllerRef.current = null;
      setIsLoading(false);
    };
    const fulfilled = (result: InfiniteFetchResult<TData, TCursor>) => {
      if (controller.signal.aborted) return;
      if (!Array.isArray(result?.rows)) {
        rejected(new TypeError("fetchRows of useDataGridInfiniteRows must resolve with { rows: TData[], nextCursor }"));
        return;
      }
      const answered = result.rows.length > limit ? result.rows.slice(0, limit) : result.rows;
      if (answered !== result.rows && !cutWarnedRef.current && isDev()) {
        cutWarnedRef.current = true;
        console.warn(`[data-grid-lazy] fetchRows returned ${result.rows.length} rows for a limit of ${limit}; only the first ${limit} are kept`);
      }
      if (result.nextCursor === undefined && !cursorWarnedRef.current && isDev()) {
        cursorWarnedRef.current = true;
        console.warn("[data-grid-lazy] fetchRows resolved without nextCursor; resolve nextCursor: null to end the source");
      }
      const nextCursor = result.nextCursor ?? null;
      const ended = nextCursor === null || answered.length === 0;
      if (answered.length === 0 && nextCursor !== null && !emptyPageWarnedRef.current && isDev()) {
        emptyPageWarnedRef.current = true;
        console.warn("[data-grid-lazy] fetchRows returned an empty page with a next cursor; an empty page ends the source, so return rows or a null cursor");
      }
      cursorRef.current = nextCursor ?? undefined;
      const next = { rows: [...loadedRef.current.rows, ...answered], hasNextPage: !ended };
      loadedRef.current = next;
      setLoaded(next);
      pendingWindowRef.current = true;
      if (answered.length > 0) guardCallback(() => optionsRef.current.onLoaded?.({ start, end: start + answered.length }));
    };
    const rejected = (error: unknown) => {
      if (controller.signal.aborted) return;
      guardCallback(() => optionsRef.current.onError?.(error));
    };

    try {
      optionsRef.current.fetchRows({ cursor: cursorRef.current, start, limit, signal: controller.signal, spec }).then(fulfilled, rejected).finally(settle);
    } catch (error) {
      rejected(error);
      settle();
    }
  }, [limit]);

  const onRenderedRowsChange = useCallback(
    (range: Range) => {
      lastWindowRef.current = range;
      if (range.end + overscan >= loadedRef.current.rows.length) fetchNext();
    },
    [overscan, fetchNext],
  );

  // No deps: a landed page re-checks the last window on the next commit, and the flag makes repeats a no-op.
  useEffect(() => {
    if (!pendingWindowRef.current) return;
    pendingWindowRef.current = false;
    if (lastWindowRef.current) onRenderedRowsChange(lastWindowRef.current);
  });

  useEffect(
    () => () => {
      controllerRef.current?.abort();
      controllerRef.current = null;
    },
    [],
  );

  const reset = useCallback(() => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    cursorRef.current = undefined;
    const fresh = { rows: [], hasNextPage: true };
    loadedRef.current = fresh;
    setLoaded(fresh);
    setIsLoading(false);
    pendingWindowRef.current = lastWindowRef.current !== null;
  }, []);

  const specKey = serverSpecKey(options.spec ?? EMPTY_SERVER_SPEC);
  const specKeyRef = useRef(specKey);
  useLayoutEffect(() => {
    if (specKeyRef.current === specKey) return;
    specKeyRef.current = specKey;
    reset();
  }, [specKey, reset]);

  const retry = useCallback(() => {
    const last = lastWindowRef.current;
    if (last) onRenderedRowsChange(last);
  }, [onRenderedRowsChange]);

  const gridGetRowId = useCallback((row: TData, index: number) => (row === undefined ? holeRowId(index) : getRowId(row, index)), [getRowId]);

  const onDataChange = useCallback(
    (next: readonly TData[], change: DataChange<TData>) => {
      const prev = loadedRef.current;
      const skeletons = prev.hasNextPage ? pageSize : 0;
      const rows =
        change.ops.length > 0
          ? (applyChange(prev.rows, change, gridGetRowId) as TData[])
          : (next.slice(0, Math.max(0, next.length - skeletons)) as TData[]);
      const merged = { rows, hasNextPage: prev.hasNextPage };
      loadedRef.current = merged;
      setLoaded(merged);
    },
    [gridGetRowId, pageSize],
  );

  const data = useMemo(() => {
    if (!loaded.hasNextPage) return loaded.rows;
    const padded = loaded.rows.slice();
    padded.length = loaded.rows.length + pageSize;
    return padded;
  }, [loaded, pageSize]);

  const totalRowCount = loaded.hasNextPage ? null : loaded.rows.length;
  const gridProps = useMemo(() => ({ data, getRowId: gridGetRowId, onRenderedRowsChange, totalRowCount }), [data, gridGetRowId, onRenderedRowsChange, totalRowCount]);

  return {
    gridProps,
    onDataChange,
    total: loaded.hasNextPage ? undefined : loaded.rows.length,
    hasNextPage: loaded.hasNextPage,
    unloadedCount: loaded.hasNextPage ? pageSize : 0,
    isLoading,
    reset,
    retry,
  };
}

"use client";

import { useEffect, useRef, type ReactNode } from "react";
import {
  useDataGridFilterState,
  useDataGridSearchText,
  useDataGridSortState,
} from "@/registry/default/components/data-grid/data-grid";
import { isDev, useDataGridSelector } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Props for {@link DataGridLazyGuard}. */
export type DataGridLazyGuardProps = {
  /** Whether unloaded rows currently exist (e.g. `lazy.unloadedCount > 0`); the warning only makes sense while data is partial. */
  hasHoles: boolean;
};

let warned = false;

/**
 * Dev-only guardrail: client-side sort/filter/search are incompatible with partial data (lazy
 * loading). Mount once inside `<DataGridProvider>`, alongside `<DataGridRoot>`. Renders nothing.
 * Sort/filter/search are only reachable here through the store's own committed state
 * (`useDataGridSortState`/`useDataGridFilterState`/`useDataGridSearchText`), because
 * `useDataGridLazyRows` runs OUTSIDE the provider and has no access to whether sort/filter is
 * controlled. A change to any of the three while holes still exist means either an uncontrolled
 * header-click/filter-menu/search gesture fired (client-side, over incomplete data) or the
 * consumer's controlled `filterState`/`searchText` changed. This guard can't tell those apart, so
 * it warns either way. Sort changes are ignored under `sortMode="server"` and filter changes under
 * `filterMode="server"`, where the server owns the order and the row set. Zero cost in production (isDev() short-circuits).
 */
export function DataGridLazyGuard({ hasHoles }: DataGridLazyGuardProps): ReactNode {
  const sortState = useDataGridSortState();
  const filterState = useDataGridFilterState();
  const searchText = useDataGridSearchText();
  const serverSort = useDataGridSelector((s) => s.sortMode === "server");
  const serverFilter = useDataGridSelector((s) => s.filterMode === "server");

  const prevRef = useRef({ sortState, filterState, searchText });
  useEffect(() => {
    const prev = prevRef.current;
    const changed = (!serverSort && prev.sortState !== sortState) || (!serverFilter && prev.filterState !== filterState) || prev.searchText !== searchText;
    prevRef.current = { sortState, filterState, searchText };
    if (!isDev() || !changed || !hasHoles || warned) return;
    warned = true;
    console.warn(
      "[data-grid-lazy] sort/filter/search changed while rows are still unloaded. Client-side sort/filter/search cannot see rows it hasn't fetched — use sortMode=\"server\" with onSortChange for sorting, filterMode=\"server\" with onFilterChange for filtering, and hand searchText to your backend, when using useDataGridLazyRows.",
    );
  }, [sortState, filterState, searchText, serverSort, serverFilter, hasHoles]);

  return null;
}

/** A half-open row range `[start, end)`, matching `onRenderedRowsChange`'s convention. */
export type Range = { start: number; end: number };

/** `end - start`, clamped to 0 for an inverted/empty range. */
export function rangeSize(range: Range): number {
  return Math.max(0, range.end - range.start);
}

/** Whether two half-open ranges overlap or touch at an edge (touching ranges are mergeable). */
function rangesAdjacentOrOverlapping(a: Range, b: Range): boolean {
  return a.start <= b.end && b.start <= a.end;
}

/**
 * Expands `range` by `overscan` rows on each side, then rounds outward so both edges land on a
 * `batchSize` boundary — small scrolls request the same batch repeatedly instead of a slightly
 * different range every tick (spec: "round ranges up so tiny scrolls don't spam requests").
 * Clamps to `[0, total]`.
 */
export function expandRange(range: Range, opts: { overscan: number; batchSize: number; total?: number }): Range {
  const { overscan, batchSize, total = Infinity } = opts;
  const withOverscan = { start: range.start - overscan, end: range.end + overscan };
  const batch = Math.max(1, batchSize);
  const start = Math.floor(withOverscan.start / batch) * batch;
  const end = Math.ceil(withOverscan.end / batch) * batch;
  return {
    start: Math.max(0, start),
    end: Math.min(total, Math.max(start, end)),
  };
}

/**
 * Subtracts every range in `covered` (already loaded or in-flight, any order/overlap) from
 * `target`, returning the remaining uncovered pieces coalesced into as few ranges as possible —
 * this is the "never re-request a loading/loaded range; merge adjacent gaps" rule as pure math.
 */
export function subtractRanges(target: Range, covered: readonly Range[]): Range[] {
  if (rangeSize(target) === 0) return [];
  const relevant = covered
    .filter((r) => rangeSize(r) > 0 && rangesAdjacentOrOverlapping(r, target))
    .map((r) => ({ start: Math.max(r.start, target.start), end: Math.min(r.end, target.end) }))
    .sort((a, b) => a.start - b.start);

  const merged: Range[] = [];
  for (const r of relevant) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }

  const gaps: Range[] = [];
  let cursor = target.start;
  for (const r of merged) {
    if (r.start > cursor) gaps.push({ start: cursor, end: r.start });
    cursor = Math.max(cursor, r.end);
  }
  if (cursor < target.end) gaps.push({ start: cursor, end: target.end });
  return gaps;
}

/** Sum of `rangeSize` across a list of ranges — callers pass an already-merged (disjoint) list so this is a true row count, not a double-count of overlaps. */
export function sumRangeSizes(ranges: readonly Range[]): number {
  return ranges.reduce((total, r) => total + rangeSize(r), 0);
}

/**
 * Splits `range` into consecutive chunks of at most `max` rows, covering it exactly once; a
 * single chunk when the range already fits. Each chunk obeys the `fetchRows` contract on its
 * own: exactly `chunk.end - chunk.start` rows, positionally aligned to `chunk.start`. A
 * fractional `max` is rounded down so every chunk boundary stays an integral row index.
 */
export function chunkRange(range: Range, max: number): Range[] {
  const size = rangeSize(range);
  const cap = Math.max(1, Math.floor(max));
  if (size <= cap) return [range];
  const chunks: Range[] = [];
  for (let start = range.start; start < range.end; start += cap) {
    chunks.push({ start, end: Math.min(range.end, start + cap) });
  }
  return chunks;
}

/** Merges a list of ranges (any order/overlap) into the minimal set of disjoint, non-touching ranges. */
export function mergeRanges(ranges: readonly Range[]): Range[] {
  const sorted = ranges
    .filter((r) => rangeSize(r) > 0)
    .slice()
    .sort((a, b) => a.start - b.start);
  const merged: Range[] = [];
  for (const r of sorted) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }
  return merged;
}

import type { FilterNode, SortSpec } from "@/registry/default/components/data-grid/data-grid";

/** The sort, filter, and search of a server request, handed to `fetchRows` so a request carries its own spec. */
export type ServerSpec = {
  sorts: readonly SortSpec[];
  filters: readonly FilterNode[];
  search: string;
};

export const EMPTY_SERVER_SPEC: ServerSpec = { sorts: [], filters: [], search: "" };

/** A spec compared by content: the generated `filterId`s change when the same filters are re-created. */
export function serverSpecKey(spec: ServerSpec): string {
  return JSON.stringify(spec, (key, value: unknown) => (key === "filterId" ? undefined : value));
}
